brand.css:
.nk{position:absolute;inset:0;pointer-events:none}
.nk .t{position:absolute;white-space:nowrap;line-height:1}
.nk .n{font-family:"Be Vietnam Pro",sans-serif;font-weight:500;font-size:var(--nk-s,46px);color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.45)}
.nk .tay{font-family:"Dancing Script",cursive;font-weight:700;font-size:var(--nk-l,160px);color:#E9FFFD;text-shadow:0 0 10px #4FE3D8,0 0 30px rgba(40,210,200,.75),0 4px 10px rgba(0,0,0,.25)}
.nk .tay.do{color:#FFE1E1;text-shadow:0 0 10px #FF4F5E,0 0 30px rgba(255,60,80,.7),0 4px 10px rgba(0,0,0,.25)}
.nk-vien{position:absolute;left:0;right:0;top:var(--nk-y,1220px);text-align:center}
.nk-vien span{display:inline-block;padding:12px 28px;border-radius:14px;background:#26C6C1;color:#fff;font-family:"Be Vietnam Pro",sans-serif;font-weight:600;font-size:var(--nk-s,44px);box-shadow:0 6px 16px rgba(0,0,0,.25)}
.nk-ic{position:absolute;left:var(--nk-x,700px);top:var(--nk-y,880px);font-size:var(--nk-e,150px);line-height:1;filter:drop-shadow(0 0 12px rgba(255,255,255,.9)) drop-shadow(0 6px 10px rgba(0,0,0,.25))}
.nk-o{position:absolute;left:50%;top:var(--nk-y,300px);width:330px;height:330px;margin-left:-165px;border-radius:40px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:190px;box-shadow:0 18px 40px rgba(0,0,0,.25)}
.nk-song{position:absolute;left:0;right:0;top:0;height:var(--nk-h,780px);background:linear-gradient(160deg,#e6e2dc,#b9b2a8);display:flex;align-items:center;justify-content:center;font-size:300px;
  clip-path:polygon(0 0,100% 0,100% 82%,85% 88%,65% 80%,45% 92%,25% 84%,0 90%)}
.nk-song::after{content:"";position:absolute;left:0;right:0;bottom:0;height:100%;clip-path:inherit;box-shadow:inset 0 -10px 0 #8FF3EC}
.nk-doi{position:absolute;left:0;right:0;top:0;height:var(--nk-h,900px);display:flex}
.nk-doi .o{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;font-size:230px;background:linear-gradient(160deg,#d9d2c4,#a89c86)}
.nk-doi .o:nth-child(2){background:linear-gradient(160deg,#f4f4f2,#d9dcdc)}
.nk-doi .o b{font-family:"Be Vietnam Pro",sans-serif;font-weight:700;font-size:40px;color:#333;background:rgba(255,255,255,.85);padding:8px 20px;border-radius:12px}
.nk-doi .vach{position:absolute;left:50%;top:0;bottom:0;width:8px;margin-left:-4px;background:#fff;box-shadow:0 0 18px rgba(255,255,255,.9)}
.nk-chop{position:absolute;inset:0;background:#fff}
.nk-mo{position:absolute;inset:0;backdrop-filter:blur(36px);-webkit-backdrop-filter:blur(36px);background:rgba(255,255,255,.12)}
